use vstd::prelude::*;

verus! {

    // Count how many i in 1..idx such that seq[i−1]=='S' and seq[i]=='F'
    spec fn count_SF_prefix(seq: Seq<char>, idx: nat) -> nat
        requires
            idx <= seq.len(),
        decreases
            idx,
    {
        if idx < 2 {
            0
        } else {
            count_SF_prefix(seq, idx - 1)
            + (if seq[idx - 2] == 'S' && seq[idx - 1] == 'F' { 1 } else { 0 })
        }
    }

    // Count how many i in 1..idx such that seq[i−1]=='F' and seq[i]=='S'
    spec fn count_FS_prefix(seq: Seq<char>, idx: nat) -> nat
        requires
            idx <= seq.len(),
        decreases
            idx,
    {
        if idx < 2 {
            0
        } else {
            count_FS_prefix(seq, idx - 1)
            + (if seq[idx - 2] == 'F' && seq[idx - 1] == 'S' { 1 } else { 0 })
        }
    }

    // solve: scan once in O(n), maintain two counters, then compare.
    fn solve(n: usize, s: Vec<char>) -> Vec<char>
        requires
            // problem preconditions
            2 <= n,
            s.len() == n,
            // all characters are either 'S' or 'F'
            forall |i: usize| i < n ==> s[i] == 'S' || s[i] == 'F',
        ensures
            // exact specification of the return value
            count_SF_prefix(s.to_seq(), n as nat) > count_FS_prefix(s.to_seq(), n as nat)
                ==> result == vec!['Y','E','S'],
        ensures
            count_SF_prefix(s.to_seq(), n as nat) <= count_FS_prefix(s.to_seq(), n as nat)
                ==> result == vec!['N','O'],
    {
        let seq = s.to_seq();
        // we will walk idx from 1 up to n, maintaining counts over the
        // prefix of length idx
        let mut idx: usize = 1;
        let mut sf: usize = 0;
        let mut fs: usize = 0;
        while idx < n
            invariant
                1 <= idx && idx <= n,
                // the two running counters agree with the spec counts
                sf == count_SF_prefix(seq, idx as nat),
                fs == count_FS_prefix(seq, idx as nat),
            decreases
                n - idx,
        {
            if s[idx-1] == 'S' && s[idx] == 'F' {
                sf = sf + 1;
            } else if s[idx-1] == 'F' && s[idx] == 'S' {
                fs = fs + 1;
            }
            idx = idx + 1;
        }
        if sf > fs {
            vec!['Y','E','S']
        } else {
            vec!['N','O']
        }
    }
}

